<?php
namespace App\Console\Commands;use App\Models\User;use App\Services\Transactions\TransactionProjector;use Illuminate\Console\Command;
class ReconcileTransactions extends Command{protected $signature='lenspic:reconcile-transactions {--dry-run}';protected $description='Reconcile safe financial transaction projections from authoritative billing and Wallet records';public function handle(TransactionProjector$p):int{$q=User::where(fn($x)=>$x->whereHas('subscriptions')->orWhereHas('wallet'));$count=$q->count();if($this->option('dry-run')){$this->info("Would reconcile transaction projections for {$count} studio account(s). No data changed.");return self::SUCCESS;}$q->chunkById(100,fn($users)=>$users->each(fn($u)=>$p->sync($u)));$this->info("Reconciled transaction projections for {$count} studio account(s).");return self::SUCCESS;}}
